<!DOCTYPE html>
<html lang="cs">
<head>
    <meta charset="utf-8">
    <meta name="viewport" content="width=device-width, initial-scale=1">
    <title>Vy&#250;&#269;tov&#225;n&#237; | TMS</title>
    <style>
        *{box-sizing:border-box}body{margin:0;background:#f4f7fb;color:#10213d;font-family:Arial,sans-serif}.page{max-width:1540px;margin:0 auto;padding:24px 28px 60px}.back{color:#173b72;font-weight:700;text-decoration:none}.head{display:flex;justify-content:space-between;gap:16px;align-items:center}h1{margin:26px 0 6px}.lead,.muted{color:#64748b}.panel{background:#fff;border:1px solid #d8e1ed;border-radius:14px;padding:18px;margin-top:18px}.filters{display:grid;grid-template-columns:1fr 1fr 1fr 1fr 1fr auto auto;gap:10px;align-items:end}.field{display:grid;gap:6px}label{font-size:13px;font-weight:700}input,select,button{font:inherit;border:1px solid #cbd5e1;border-radius:8px;padding:10px;min-width:0}button{background:#173b72;color:#fff;border:0;font-weight:700;cursor:pointer}.secondary{background:#e8eef7;color:#173b72}.table-wrap{overflow:auto}table{width:100%;border-collapse:collapse;margin-top:14px;min-width:1280px}th,td{padding:11px;border-bottom:1px solid #e5e7eb;text-align:left;vertical-align:top}th{background:#f8fafc;font-size:13px}.badge{display:inline-block;padding:5px 8px;border-radius:999px;background:#e2e8f0;font-size:12px;font-weight:700}.approved,.closed{background:#dcfce7;color:#166534}.under_review{background:#dbeafe;color:#1e40af}.cancelled{background:#fee2e2;color:#991b1b}.draft{background:#e2e8f0;color:#334155}.positive{color:#166534}.negative{color:#b91c1c}.footer{display:flex;justify-content:space-between;align-items:center;margin-top:14px}.pager{display:flex;gap:8px;align-items:center}.message{margin-top:12px;padding:10px;border-radius:8px;background:#eef2ff}.error{background:#fee2e2;color:#991b1b}.hidden{display:none!important}.modal{position:fixed;inset:0;background:#0008;display:grid;place-items:center;padding:20px;z-index:5}.dialog{width:min(1120px,100%);max-height:92vh;overflow:auto;background:#fff;border-radius:14px;padding:20px}.cards{display:grid;grid-template-columns:repeat(5,1fr);gap:10px}.card{background:#f8fafc;border:1px solid #e2e8f0;border-radius:10px;padding:12px}.card span{display:block;color:#64748b;font-size:12px}.card strong{display:block;margin-top:6px}.detail-table{min-width:900px}.audit-item{padding:10px 0;border-bottom:1px solid #e2e8f0}.materialization-form{display:grid;gap:16px;margin-top:16px}.form-section{margin:0;border:1px solid #d8e1ed;border-radius:12px;padding:16px;background:#f8fafc}.form-section legend{padding:0 8px;color:#173b72;font-size:15px;font-weight:700}.form-note{margin:0 0 14px;color:#64748b;font-size:13px}.required-note{margin:12px 0 0;color:#64748b;font-size:12px}.form-grid{display:grid;grid-template-columns:repeat(2,minmax(240px,1fr));gap:14px 16px}.amount-grid{grid-template-columns:repeat(4,minmax(155px,1fr))}.field-wide{grid-column:1/-1}.materialization-form input,.materialization-form select{width:100%;min-height:44px;background:#fff}.materialization-form input[type=date]{min-width:190px}.required>label:after{content:' *';color:#b91c1c}.materialization-actions{display:flex;justify-content:flex-start;margin-top:16px}@media(max-width:900px){.amount-grid{grid-template-columns:repeat(2,minmax(200px,1fr))}}@media(max-width:650px){.form-grid,.amount-grid{grid-template-columns:1fr}.field-wide{grid-column:auto}.materialization-form input[type=date]{min-width:0}}.bank-grid{display:grid;grid-template-columns:repeat(3,minmax(160px,1fr));gap:10px}.bank-actions{display:flex;flex-wrap:wrap;gap:8px}.bank-actions button{padding:7px 9px}.score{font-variant-numeric:tabular-nums}.unpaid{background:#fee2e2;color:#991b1b}.partially_paid{background:#fef3c7;color:#92400e}.paid,.active{background:#dcfce7;color:#166534}.reversed,.rejected,.superseded{background:#e2e8f0;color:#475569}.proposed{background:#dbeafe;color:#1e40af}.accepted{background:#dcfce7;color:#166534}@media(max-width:1050px){.filters{grid-template-columns:repeat(3,1fr)}.cards,.bank-grid{grid-template-columns:repeat(3,1fr)}}@media(max-width:600px){.page{padding:18px}.filters,.cards{grid-template-columns:1fr}}
    </style>
</head>
<body>
<main class="page">
    <div class="head"><a class="back" href="/settings">&larr; Nastaven&#237;</a><div class="bank-actions"><button id="openBankEvidence" class="secondary">Bankovn&#237; evidence</button><button id="exportReconciliation" class="secondary">Exportovat reconcilace CSV</button><button id="refresh" class="secondary">Obnovit</button></div></div>
    <h1>Vy&#250;&#269;tov&#225;n&#237; &#345;idi&#269;&#367; a dopravc&#367;</h1>
    <p class="lead">Spr&#225;va vy&#250;&#269;tov&#225;n&#237; &#345;idi&#269;&#367; a dopravc&#367; v&#269;etn&#283; auditovan&#253;ch zm&#283;n stavu a vytvo&#345;en&#237; v&#253;sledn&#233;ho v&#253;stupu.</p>
    <section class="panel">
        <div class="filters">
            <div class="field"><label for="status">Stav</label><select id="status"><option value="">V&#353;echny</option><option value="draft">Koncept</option><option value="under_review">Ke kontrole</option><option value="approved">Schv&#225;leno</option><option value="closed">Uzav&#345;eno</option><option value="cancelled">Stornov&#225;no</option></select></div>
            <div class="field"><label for="partyType">P&#345;&#237;jemce</label><select id="partyType"><option value="">V&#353;ichni</option><option value="organization">Extern&#237; dopravce</option><option value="driver">&#344;idi&#269;</option></select></div>
            <div class="field"><label for="direction">Sm&#283;r v&#253;stupu</label><select id="direction"><option value="">V&#353;echny</option><option value="receivable">Pohled&#225;vka</option><option value="payable">Z&#225;vazek</option></select></div>
            <div class="field"><label for="periodFrom">Obdob&#237; od</label><input id="periodFrom" type="date"></div>
            <div class="field"><label for="periodUntil">Obdob&#237; do</label><input id="periodUntil" type="date"></div>
            <button id="filter">Filtrovat</button><button id="reset" class="secondary">Zru&#353;it filtr</button>
        </div>
        <div id="message" class="message hidden"></div>
        <div class="table-wrap"><table><thead><tr><th>P&#345;&#237;jemce</th><th>Obdob&#237;</th><th>V&#253;nosy</th><th>Sr&#225;&#382;ky</th><th>&#268;ist&#233; saldo</th><th>Stav</th><th>V&#253;stup</th><th>Platba</th><th>Uhrazeno</th><th>Zb&#253;v&#225; uhradit</th><th>Doklad</th><th>Akce</th></tr></thead><tbody id="rows"></tbody></table></div>
        <div class="footer"><span id="total">Celkem 0 vy&#250;&#269;tov&#225;n&#237;</span><div class="pager"><button id="previous" class="secondary">P&#345;edchoz&#237;</button><span id="pageInfo">Strana 1 z 1</span><button id="next" class="secondary">Dal&#353;&#237;</button></div></div>
    </section>
    @include('mvp.partials.financial-settlement-accounting-period-administration')
    @include('mvp.partials.financial-settlement-accounting-posting-administration')
</main>
<div id="bankEvidenceModal" class="modal hidden"><section class="dialog"><div class="head"><h2>Bankovn&#237; evidence</h2><button id="closeBankEvidence" class="secondary">Zav&#345;&#237;t</button></div><p class="muted">P&#345;ehled je pouze pro &#269;ten&#237;. Kapacita zahrnuje aktivn&#237; vazby na vy&#250;&#269;tov&#225;n&#237;, palivo a n&#225;klady vozidel.</p><div class="filters"><div class="field"><label for="evidenceDirection">Sm&#283;r</label><select id="evidenceDirection"><option value="">V&#353;echny</option><option value="credit">P&#345;&#237;jem</option><option value="debit">V&#253;dej</option></select></div><div class="field"><label for="evidenceCurrency">M&#283;na</label><input id="evidenceCurrency" maxlength="3"></div><div class="field"><label for="evidenceBookedFrom">Za&#250;&#269;tov&#225;no od</label><input id="evidenceBookedFrom" type="date"></div><div class="field"><label for="evidenceBookedUntil">Za&#250;&#269;tov&#225;no do</label><input id="evidenceBookedUntil" type="date"></div><div class="field"><label for="evidenceReference">Reference</label><input id="evidenceReference"></div><button id="filterBankEvidence">Filtrovat</button><button id="resetBankEvidence" class="secondary">Zru&#353;it filtr</button></div><div class="table-wrap"><table class="detail-table"><thead><tr><th>Reference</th><th>Datum</th><th>Protistrana</th><th>&#268;&#225;stka</th><th>Vyu&#382;ito</th><th>Zb&#253;v&#225;</th><th>Kapacita</th><th>Akce</th></tr></thead><tbody id="bankEvidenceRows"></tbody></table></div><div id="bankEvidenceDetail" class="panel hidden"></div></section></div>
<div id="detailModal" class="modal hidden"><section class="dialog"><div class="head"><h2 id="detailTitle">Detail vy&#250;&#269;tov&#225;n&#237;</h2><button id="closeDetail" class="secondary">Zav&#345;&#237;t</button></div><div id="detailCards" class="cards"></div><div id="lifecycleActions" class="head" style="justify-content:flex-start;margin-top:14px"></div><section id="materializationPanel" class="panel hidden"><h3>Vytvo&#345;it v&#253;stup vy&#250;&#269;tov&#225;n&#237;</h3><p class="muted">Materializace je samostatn&#253; auditovan&#253; krok. Nevytv&#225;&#345;&#237; platbu ani bankovn&#237; sp&#225;rov&#225;n&#237;.</p><div id="carrierDocumentFields" class="materialization-form hidden">
    <p class="form-note">Vypl&#328;te identifikaci obchodn&#237;ho dokladu a zkontrolujte p&#345;esn&#233; &#269;&#225;stky p&#345;ed jeho vytvo&#345;en&#237;m.</p>
    <fieldset class="form-section">
        <legend>Doklad a term&#237;ny</legend>
        <div class="form-grid">
            <div class="field required"><label for="documentNumber">&#268;&#237;slo dokladu</label><input id="documentNumber" maxlength="64" autocomplete="off"></div>
            <div class="field"><label for="variableSymbol">Variabiln&#237; symbol</label><input id="variableSymbol" maxlength="32" inputmode="numeric"></div>
            <div class="field required"><label for="issuedOn">Datum vystaven&#237;</label><input id="issuedOn" type="date"></div>
            <div class="field required"><label for="dueOn">Splatnost</label><input id="dueOn" type="date"></div>
        </div>
    </fieldset>
    <fieldset class="form-section">
        <legend>Protistrana</legend>
        <div class="form-grid">
            <div class="field field-wide required"><label for="counterpartyName">N&#225;zev protistrany</label><input id="counterpartyName" maxlength="255" autocomplete="organization"></div>
            <div class="field"><label for="registrationNumber">I&#268;O</label><input id="registrationNumber" maxlength="64" inputmode="numeric"></div>
            <div class="field"><label for="vatNumber">DI&#268;</label><input id="vatNumber" maxlength="64"></div>
            <div class="field field-wide"><label for="accountIdentifier">Bankovn&#237; &#250;&#269;et</label><input id="accountIdentifier" maxlength="128"></div>
        </div>
    </fieldset>
    <fieldset class="form-section">
        <legend>&#268;&#225;stky a DPH</legend>
        <div class="form-grid amount-grid">
            <div class="field required"><label for="vatTreatment">Re&#382;im DPH</label><select id="vatTreatment"><option value="not_applicable">Bez DPH</option><option value="standard">Standardn&#237; DPH</option></select></div>
            <div class="field required"><label for="netAmount">Netto v K&#269;</label><input id="netAmount" inputmode="decimal" pattern="[0-9]+\.[0-9]{2}"></div>
            <div class="field required"><label for="vatAmount">DPH v K&#269;</label><input id="vatAmount" inputmode="decimal" pattern="[0-9]+\.[0-9]{2}" value="0.00"></div>
            <div class="field"><label for="vatRate">Sazba DPH v %</label><input id="vatRate" type="number" min="0" max="100" step="0.01"></div>
        </div>
        <p class="required-note"><span aria-hidden="true">*</span> Povinn&#233; pole. &#268;&#225;stky se zad&#225;vaj&#237; p&#345;esn&#283; na dv&#283; desetinn&#225; m&#237;sta.</p>
    </fieldset>
</div><div class="field" style="margin-top:12px"><label for="materializationReason">D&#367;vod</label><input id="materializationReason" minlength="3" maxlength="1000" value="Vytvo&#345;en&#237; v&#253;stupu schv&#225;len&#233;ho vy&#250;&#269;tov&#225;n&#237;."></div><div class="materialization-actions"><button id="materializeOutput">Vytvo&#345;it v&#253;stup</button></div></section><section id="bankPaymentAdministration" class="panel"><h3>Bankovn&#237; platby vy&#250;&#269;tov&#225;n&#237;</h3><div id="paymentSummary" class="bank-grid"></div><div id="proposalControls" class="bank-grid" style="margin-top:14px"><div class="field"><label for="minimumScore">Minim&#225;ln&#237; sk&#243;re</label><input id="minimumScore" type="number" min="1" max="10000" value="6000"></div><div class="field"><label for="dateWindow">Okno dn&#237;</label><input id="dateWindow" type="number" min="0" max="366" value="7"></div><div class="field"><label for="matchingReason">D&#367;vod n&#225;vrhu</label><input id="matchingReason" minlength="3" maxlength="1000" value="N&#225;vrh bankovn&#237;ho p&#225;rov&#225;n&#237; vy&#250;&#269;tov&#225;n&#237;."></div></div><div class="bank-actions" style="margin-top:10px"><button id="proposeMatch">Navrhnout bankovn&#237; shodu</button></div><h4>Kandid&#225;ti</h4><div class="table-wrap"><table class="detail-table"><thead><tr><th>Bankovn&#237; evidence</th><th>Navr&#382;eno</th><th>Sk&#243;re a d&#367;vody</th><th>Stav</th><th>Akce</th></tr></thead><tbody id="candidateRows"></tbody></table></div><h4>Platby a storna</h4><div class="table-wrap"><table class="detail-table"><thead><tr><th>Platba</th><th>Evidence</th><th>&#268;&#225;stka</th><th>Stav platby</th><th>Reconcilace</th><th>Audit</th><th>Akce</th></tr></thead><tbody id="paymentRows"></tbody></table></div></section><h3>Zdrojov&#233; &#345;&#225;dky</h3><div class="table-wrap"><table class="detail-table"><thead><tr><th>Po&#345;ad&#237;</th><th>Zdroj</th><th>Popis</th><th>Efekt</th><th>&#268;&#225;stka</th><th>Revize</th></tr></thead><tbody id="lineRows"></tbody></table></div><h3>Auditn&#237; historie</h3><div id="audit"></div></section></div>
<script>
const token=sessionStorage.getItem('tms_mvp_token')||'';
const organization=sessionStorage.getItem('tms_mvp_organization_id')||'1';
let page=1,lastPage=1,activeStatement=null;
const esc=value=>String(value??'').replace(/[&<>"]/g,char=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[char]));
const labels={draft:'Koncept',under_review:'Ke kontrole',approved:'Schvaleno',closed:'Uzavreno',cancelled:'Stornovano',organization:'Externi dopravce',driver:'Ridic',receivable:'Pohledavka',payable:'Zavazek',earning:'Vynos',deduction:'Srazka',unpaid:'Neuhrazeno',partially_paid:'ÄŚĂˇsteÄŤnÄ› uhrazeno',paid:'Uhrazeno',proposed:'Navrzeno',accepted:'Prijato',rejected:'Zamitnuto',superseded:'Nahrazeno',active:'Aktivni',reversed:'Stornovano'};
const money=(minor,currency)=>new Intl.NumberFormat('cs-CZ',{style:'currency',currency:currency||'CZK'}).format(Number(minor||0)/100);
const date=value=>value?new Intl.DateTimeFormat('cs-CZ').format(new Date(value)):'-';
const netClass=value=>Number(value)<0?'negative':'positive';
function message(text,error=false){const node=document.querySelector('#message');node.textContent=text;node.className=text?`message${error?' error':''}`:'message hidden'}
async function api(path,options={}){const headers=new Headers(options.headers||{});headers.set('Accept','application/json');headers.set('X-Organization-ID',organization);if(token)headers.set('Authorization',`Bearer ${token}`);const response=await fetch(path,{...options,headers});const payload=await response.json().catch(()=>({}));if(!response.ok)throw new Error(payload.message||`HTTP ${response.status}`);return payload.data||payload}
function query(){const params=new URLSearchParams({page:String(page),per_page:'25'});for(const [id,key] of [['status','status'],['partyType','party_type'],['direction','direction'],['periodFrom','period_from'],['periodUntil','period_until']]){const value=document.querySelector(`#${id}`).value.trim();if(value)params.set(key,value)}return params}
function recipient(item){return `${labels[item.recipient_type]||item.recipient_type} #${item.recipient_organization_id||item.recipient_driver_id||'-'}`}
function output(item){return item.output_kind?`${item.output_kind} | ${labels[item.output_direction]||item.output_direction||'-'}`:'Dosud bez vystupu'}
function compactId(value){const text=String(value||'');return text.length>18?`${text.slice(0,8)}\u2026${text.slice(-6)}`:(text||'\u2014')}
function paymentStateLabel(value){return ({unpaid:'Neuhrazeno',partially_paid:'\u010c\u00e1ste\u010dn\u011b uhrazeno',paid:'Uhrazeno'})[value]||value||'Neuhrazeno'}
function paymentStateClass(value){return value==='paid'?'accepted':(value==='partially_paid'?'superseded':'rejected')}
function outputLabel(value){return ({carrier_payable:'Z\u00e1vazek v\u016f\u010di dopravci',carrier_receivable:'Pohled\u00e1vka za dopravcem',driver_payout:'V\u00fdplata \u0159idi\u010di',driver_deduction:'Sr\u00e1\u017eka \u0159idi\u010de',zero_balance:'Nulov\u00e9 saldo'})[value]||value||'\u2014'}
function auditLabel(value){return ({payment_allocated:'Platba p\u0159i\u0159azena',payment_reversed:'Platba stornov\u00e1na',candidate_proposed:'Kandid\u00e1t navr\u017een',candidate_accepted:'Kandid\u00e1t p\u0159ijat',candidate_rejected:'Kandid\u00e1t odm\u00edtnut',candidate_superseded:'Kandid\u00e1t nahrazen',reconciliation_confirmed:'Reconcilace potvrzena',reconciliation_reopened:'Reconcilace znovu otev\u0159ena'})[value]||value||'\u2014'}
async function exportReconciliation(){try{message('');const response=await fetch(`/api/v1/financial-settlement-statements/reconciliation-export?${query()}`,{headers:{'Accept':'text/csv','X-Organization-ID':organization,...(token?{'Authorization':`Bearer ${token}`}:{})}});if(!response.ok){const payload=await response.json().catch(()=>({}));throw new Error(payload.message||`HTTP ${response.status}`)}const blob=await response.blob(),disposition=response.headers.get('Content-Disposition')||'',match=disposition.match(/filename="?([^";]+)"?/i),name=match?.[1]||'reconcilace-vyuctovani.csv',url=URL.createObjectURL(blob),link=document.createElement('a');link.href=url;link.download=name;document.body.appendChild(link);link.click();link.remove();URL.revokeObjectURL(url);message('Export reconcilaci byl pripraven.')}catch(error){message(error.message,true)}}
async function load(){try{message('');const data=await api(`/api/v1/financial-settlement-statements?${query()}`),items=data.items||[],pagination=data.pagination||{};lastPage=pagination.last_page||1;document.querySelector('#rows').innerHTML=items.map(item=>`<tr><td><b>${esc(recipient(item))}</b><br><span class="muted">${esc(compactId(item.public_id))}</span></td><td>${esc(date(item.period_from))} - ${esc(date(item.period_until))}</td><td>${esc(money(item.earning_amount_minor,item.currency))}</td><td>${esc(money(item.deduction_amount_minor,item.currency))}</td><td class="${netClass(item.net_balance_minor)}"><b>${esc(money(item.net_balance_minor,item.currency))}</b></td><td><span class="badge ${esc(item.status)}">${esc(labels[item.status]||item.status)}</span><br><span class="muted">revize ${esc(item.revision)}</span></td><td>${esc(outputLabel(item.output_kind))}</td><td><span class="badge ${esc(paymentStateClass(item.settlement_payment_state))}">${esc(paymentStateLabel(item.settlement_payment_state))}</span></td><td><b>${esc(money(item.settlement_paid_amount_minor||0,item.currency))}</b></td><td><b>${esc(money(item.settlement_remaining_amount_minor??item.net_balance_minor,item.currency))}</b></td><td title="${esc(item.billing_document?.public_id||'')}">${esc(item.billing_document?.document_number||compactId(item.billing_document?.public_id)||'-')}</td><td><button class="secondary" data-detail="${esc(item.public_id)}">Otev&#345;&#237;t detail</button></td></tr>`).join('')||'<tr><td colspan="12">&#381;&#225;dn&#225; vy&#250;&#269;tov&#225;n&#237;.</td></tr>';document.querySelector('#total').textContent=`Celkem ${pagination.total||0} vy\u00fa\u010dtov\u00e1n\u00ed`;document.querySelector('#pageInfo').textContent=`Strana ${pagination.current_page||1} z ${lastPage}`;document.querySelector('#previous').disabled=page<=1;document.querySelector('#next').disabled=page>=lastPage;document.querySelectorAll('[data-detail]').forEach(button=>button.onclick=()=>openDetail(button.dataset.detail))}catch(error){message(error.message,true)}}
const decimalMinor=minor=>(Math.abs(Number(minor||0))/100).toFixed(2);
function renderMaterialization(item){const available=item.status==='closed'&&!item.output_kind&&!item.billing_document,panel=document.querySelector('#materializationPanel'),carrierFields=document.querySelector('#carrierDocumentFields');panel.classList.toggle('hidden',!available);if(!available)return;const carrier=item.recipient_type==='organization'&&Number(item.net_balance_minor)!==0;carrierFields.classList.toggle('hidden',!carrier);const today=new Date().toISOString().slice(0,10);document.querySelector('#issuedOn').value=today;document.querySelector('#dueOn').value=today;document.querySelector('#netAmount').value=decimalMinor(item.net_balance_minor);document.querySelector('#vatAmount').value='0.00';document.querySelector('#vatTreatment').value='not_applicable';document.querySelector('#vatRate').value=''}
function carrierDocumentPayload(){const treatment=document.querySelector('#vatTreatment').value,payload={document_number:document.querySelector('#documentNumber').value.trim(),variable_symbol:document.querySelector('#variableSymbol').value.trim()||null,issued_on:document.querySelector('#issuedOn').value,due_on:document.querySelector('#dueOn').value,counterparty_name:document.querySelector('#counterpartyName').value.trim(),counterparty_registration_number:document.querySelector('#registrationNumber').value.trim()||null,counterparty_vat_number:document.querySelector('#vatNumber').value.trim()||null,counterparty_account_identifier:document.querySelector('#accountIdentifier').value.trim()||null,vat_treatment:treatment,net_amount:document.querySelector('#netAmount').value.trim(),vat_amount:document.querySelector('#vatAmount').value.trim()};if(treatment==='standard')payload.vat_rate_basis_points=Math.round(Number(document.querySelector('#vatRate').value)*100);return payload}
async function materializeOutput(){if(!activeStatement)return;const reason=document.querySelector('#materializationReason').value.trim();if(reason.length<3){message('Duvod musi mit alespon 3 znaky.',true);return}const carrier=activeStatement.recipient_type==='organization'&&Number(activeStatement.net_balance_minor)!==0;const payload={idempotency_key:crypto.randomUUID(),expected_revision:Number(activeStatement.revision),reason,...(carrier?carrierDocumentPayload():{})};try{await api(`/api/v1/financial-settlement-statements/${activeStatement.public_id}/materialize-output`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)});message('Vystup vyuctovani byl vytvoren bez oznaceni platby.');await openDetail(activeStatement.public_id);await load()}catch(error){message(error.message,true)}}
function renderLifecycleActions(item){const actions=[];if(item.status==='draft')actions.push(['submit','Predat ke kontrole','']);if(item.status==='under_review')actions.push(['approve','Schvalit','']);if(item.status==='approved')actions.push(['close','Uzavrit','']);const mayCancel=['under_review','approved','closed'].includes(item.status)&&!item.output_kind&&!item.billing_document;if(mayCancel)actions.push(['cancel','Stornovat','secondary']);document.querySelector('#lifecycleActions').innerHTML=actions.map(([action,label,style])=>`<button class="${style}" data-lifecycle-action="${action}">${label}</button>`).join('');document.querySelectorAll('[data-lifecycle-action]').forEach(button=>button.onclick=()=>transitionStatement(button.dataset.lifecycleAction))}
async function transitionStatement(action){if(!activeStatement)return;const reason=prompt('Uvedte duvod akce (alespon 3 znaky):','Rucni rozhodnuti nad vyuctovanim.');if(reason===null||reason.trim().length<3)return;try{await api(`/api/v1/financial-settlement-statements/${activeStatement.public_id}/transitions`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({action,idempotency_key:crypto.randomUUID(),expected_revision:Number(activeStatement.revision),reason:reason.trim()})});message('Lifecycle akce byla auditne ulozena.');await openDetail(activeStatement.public_id);await load()}catch(error){message(error.message,true)}}
function evidenceQuery(){const values={direction:document.querySelector('#evidenceDirection').value,currency:document.querySelector('#evidenceCurrency').value.trim().toUpperCase(),booked_from:document.querySelector('#evidenceBookedFrom').value,booked_until:document.querySelector('#evidenceBookedUntil').value,reference:document.querySelector('#evidenceReference').value.trim()};return new URLSearchParams(Object.entries(values).filter(([,value])=>value)).toString()}
function capacityLabel(value){return({available:'Voln&#225;',partially_allocated:'&#268;&#225;ste&#269;n&#283; vyu&#382;it&#225;',fully_allocated:'Pln&#283; vyu&#382;it&#225;',over_allocated:'P&#345;ekro&#269;en&#225;'})[value]||value}
async function loadBankEvidence(){try{const data=await api(`/api/v1/bank-transaction-evidence?${evidenceQuery()}`),items=data.items||[];document.querySelector('#bankEvidenceRows').innerHTML=items.map(item=>`<tr><td><b>${esc(item.source_reference||'-')}</b><br><span class="muted">${esc(compactId(item.public_id))}</span></td><td>${esc(date(item.booked_at))}</td><td>${esc(item.counterparty_name||'-')}</td><td><b>${esc(money(item.amount_minor,item.currency))}</b></td><td>${esc(money(item.allocated_amount_minor,item.currency))}</td><td>${esc(money(item.remaining_capacity_amount_minor,item.currency))}</td><td><span class="badge ${esc(item.capacity_state)}">${capacityLabel(item.capacity_state)}</span></td><td><button class="secondary" data-evidence-detail="${esc(item.public_id)}">Otev&#345;&#237;t detail</button></td></tr>`).join('')||'<tr><td colspan="8">&#381;&#225;dn&#225; bankovn&#237; evidence.</td></tr>';document.querySelectorAll('[data-evidence-detail]').forEach(button=>button.onclick=()=>openBankEvidenceDetail(button.dataset.evidenceDetail))}catch(error){message(error.message,true)}}
async function openBankEvidenceDetail(id){try{const item=await api(`/api/v1/bank-transaction-evidence/${id}`),links=[['Kandid&#225;ti vy&#250;&#269;tov&#225;n&#237;',item.settlement_candidates],['Platby vy&#250;&#269;tov&#225;n&#237;',item.settlement_payments],['Reconcilace',item.reconciliations],['Platby paliva',item.supplier_fuel_payments],['P&#225;rov&#225;n&#237; n&#225;klad&#367; vozidel',item.vehicle_cost_matches]];document.querySelector('#bankEvidenceDetail').innerHTML=`<h3>${esc(item.source_reference||compactId(item.public_id))}</h3><div class="bank-grid"><div class="card"><span>Celkem</span><strong>${esc(money(item.amount_minor,item.currency))}</strong></div><div class="card"><span>Vyu&#382;ito</span><strong>${esc(money(item.allocated_amount_minor,item.currency))}</strong></div><div class="card"><span>Zb&#253;v&#225;</span><strong>${esc(money(item.remaining_capacity_amount_minor,item.currency))}</strong></div></div>${links.map(([label,rows])=>`<h4>${label}</h4><p>${(rows||[]).length?rows.map(row=>esc(row.public_id||row.status||'-')).join('<br>'):'Bez vazeb.'}</p>`).join('')}<h4>Rozpad &#269;&#225;stky</h4><p>${(item.amount_breakdowns||[]).length} z&#225;znam&#367;</p><h4>Auditn&#237; historie</h4><p>${eventSummary(item.events)}</p>`;document.querySelector('#bankEvidenceDetail').classList.remove('hidden')}catch(error){message(error.message,true)}}
function eventSummary(events){return(events||[]).map(event=>`${esc(auditLabel(event.event_type))} (rev. ${esc(event.revision)})`).join('<br>')||'-'}
function reasonSummary(reasons){return Object.entries(reasons||{}).filter(([,value])=>value===true).map(([key])=>esc(key)).join(', ')||'-'}
function reconciliationState(payment){return payment.reconciliation?.status||'not_confirmed'}
function reconciliationLabel(value){return({confirmed:'Potvrzeno',open:'Znovu otevreno',not_confirmed:'Nepotvrzeno'})[value]||value}
function reconciliationActions(payment,manageable){if(!manageable||payment.status!=='active')return'-';const reconciliation=payment.reconciliation;if(reconciliation?.status==='confirmed')return`<button class="secondary" data-reopen-reconciliation="${esc(payment.public_id)}" data-reconciliation-revision="${esc(reconciliation.revision)}">Znovu otevrit</button>`;return`<button data-confirm-reconciliation="${esc(payment.public_id)}" data-payment-revision="${esc(payment.revision)}" data-reconciliation-revision="${esc(reconciliation?.revision||0)}">Potvrdit kontrolu</button>`}
function renderBankAdministration(item){const manageable=Boolean(item.can_manage_settlement_bank_payments),state=item.settlement_payment_state||'unpaid';document.querySelector('#paymentSummary').innerHTML=`<div class="card"><span>Stav platby</span><strong><span class="badge ${esc(state)}">${esc(labels[state]||state)}</span></strong></div><div class="card"><span>Uhrazeno</span><strong>${esc(money(item.settlement_paid_amount_minor,item.currency))}</strong></div><div class="card"><span>Zb&#253;v&#225; uhradit</span><strong>${esc(money(item.settlement_remaining_amount_minor,item.currency))}</strong></div>`;document.querySelector('#proposalControls').classList.toggle('hidden',!manageable||Number(item.settlement_remaining_amount_minor)<=0);document.querySelector('#proposeMatch').classList.toggle('hidden',!manageable||Number(item.settlement_remaining_amount_minor)<=0);document.querySelector('#candidateRows').innerHTML=(item.bank_match_candidates||[]).map(candidate=>{const actions=[];if(manageable&&candidate.status==='proposed'){for(const decision of ['accepted','rejected','superseded'])actions.push(`<button class="secondary" data-candidate-decision="${decision}" data-candidate="${esc(candidate.public_id)}" data-revision="${esc(candidate.revision)}">${esc(labels[decision])}</button>`)}if(manageable&&candidate.status==='accepted'&&!candidate.payment_public_id)actions.push(`<button data-materialize="${esc(candidate.public_id)}" data-revision="${esc(candidate.revision)}">Vytvorit platbu</button>`);return`<tr><td>${esc(candidate.bank_source_reference||candidate.bank_transaction_evidence_public_id||'-')}</td><td><b>${esc(money(candidate.proposed_amount_minor,candidate.currency))}</b></td><td><span class="score">${esc(candidate.score_basis_points)} / 10000</span><br><span class="muted">${reasonSummary(candidate.match_reasons)}</span></td><td><span class="badge ${esc(candidate.status)}">${esc(labels[candidate.status]||candidate.status)}</span><br><span class="muted">revize ${esc(candidate.revision)}</span></td><td><div class="bank-actions">${actions.join('')}</div></td></tr>`}).join('')||'<tr><td colspan="5">Bez kandidatu bankovniho parovani.</td></tr>';document.querySelector('#paymentRows').innerHTML=(item.bank_payments||[]).map(payment=>{const reconciliation=payment.reconciliation,reconciliationStatus=reconciliationState(payment);return`<tr><td>${esc(compactId(payment.public_id))}</td><td>${esc(payment.bank_transaction_evidence?.source_reference||compactId(payment.bank_transaction_evidence?.public_id)||'-')}</td><td><b>${esc(money(payment.allocated_amount_minor,payment.currency))}</b></td><td><span class="badge ${esc(payment.status)}">${esc(labels[payment.status]||payment.status)}</span><br><span class="muted">revize ${esc(payment.revision)}</span></td><td><span class="badge ${esc(reconciliationStatus)}">${esc(reconciliationLabel(reconciliationStatus))}</span><br><span class="muted">revize ${esc(reconciliation?.revision||0)}</span><br>${eventSummary(reconciliation?.events)}</td><td>${eventSummary(payment.events)}</td><td><div class="bank-actions">${reconciliationActions(payment,manageable)}${manageable&&payment.status==='active'?`<button class="secondary" data-reverse-payment="${esc(payment.public_id)}" data-revision="${esc(payment.revision)}">Stornovat platbu</button>`:''}</div></td></tr>`}).join('')||'<tr><td colspan="7">Bez materializovanych plateb.</td></tr>';document.querySelectorAll('[data-candidate-decision]').forEach(button=>button.onclick=()=>reviewCandidate(button.dataset.candidate,button.dataset.candidateDecision,Number(button.dataset.revision)));document.querySelectorAll('[data-materialize]').forEach(button=>button.onclick=()=>materializeCandidate(button.dataset.materialize,Number(button.dataset.revision)));document.querySelectorAll('[data-confirm-reconciliation]').forEach(button=>button.onclick=()=>confirmReconciliation(button.dataset.confirmReconciliation,Number(button.dataset.paymentRevision),Number(button.dataset.reconciliationRevision)));document.querySelectorAll('[data-reopen-reconciliation]').forEach(button=>button.onclick=()=>reopenReconciliation(button.dataset.reopenReconciliation,Number(button.dataset.reconciliationRevision)));document.querySelectorAll('[data-reverse-payment]').forEach(button=>button.onclick=()=>reversePayment(button.dataset.reversePayment,Number(button.dataset.revision)))}
async function proposeMatch(){if(!activeStatement)return;const reason=document.querySelector('#matchingReason').value.trim();if(reason.length<3){message('Duvod musi mit alespon 3 znaky.',true);return}try{await api(`/api/v1/financial-settlement-statements/${activeStatement.public_id}/bank-match-candidates`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({idempotency_key:crypto.randomUUID(),minimum_score_basis_points:Number(document.querySelector('#minimumScore').value),date_window_days:Number(document.querySelector('#dateWindow').value),reason})});message('Kandidat bankovniho parovani byl navrzen.');await openDetail(activeStatement.public_id)}catch(error){message(error.message,true)}}
async function reviewCandidate(candidate,decision,revision){const reason=prompt('Uvedte duvod rozhodnuti (alespon 3 znaky):','Rucni kontrola bankovniho parovani.');if(reason===null||reason.trim().length<3)return;try{await api(`/api/v1/financial-settlement-statements/${activeStatement.public_id}/bank-match-candidates/${candidate}/review`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({idempotency_key:crypto.randomUUID(),expected_revision:revision,decision,reason:reason.trim()})});await openDetail(activeStatement.public_id)}catch(error){message(error.message,true)}}
async function materializeCandidate(candidate,revision){const reason=prompt('Uvedte duvod vytvoreni platby (alespon 3 znaky):','Schvalene bankovni parovani vyuctovani.');if(reason===null||reason.trim().length<3)return;try{await api(`/api/v1/financial-settlement-statements/${activeStatement.public_id}/bank-match-candidates/${candidate}/materialize`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({idempotency_key:crypto.randomUUID(),expected_candidate_revision:revision,reason:reason.trim()})});message('Platba vyuctovani byla vytvorena.');await openDetail(activeStatement.public_id);await load()}catch(error){message(error.message,true)}}
async function confirmReconciliation(payment,paymentRevision,reconciliationRevision){const reason=prompt('Uvedte duvod potvrzeni reconcilace (alespon 3 znaky):','Rucni kontrola bankovni platby vyuctovani.');if(reason===null||reason.trim().length<3)return;try{await api(`/api/v1/financial-settlement-statements/${activeStatement.public_id}/bank-payments/${payment}/reconciliation/confirm`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({idempotency_key:crypto.randomUUID(),expected_payment_revision:paymentRevision,expected_reconciliation_revision:reconciliationRevision,reason:reason.trim()})});message('Reconcilace platby byla potvrzena.');await openDetail(activeStatement.public_id)}catch(error){message(error.message,true)}}
async function reopenReconciliation(payment,reconciliationRevision){const reason=prompt('Uvedte duvod znovuotevreni reconcilace (alespon 3 znaky):','Dodatecna kontrola bankovni platby vyuctovani.');if(reason===null||reason.trim().length<3)return;try{await api(`/api/v1/financial-settlement-statements/${activeStatement.public_id}/bank-payments/${payment}/reconciliation/reopen`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({idempotency_key:crypto.randomUUID(),expected_revision:reconciliationRevision,reason:reason.trim()})});message('Reconcilace platby byla znovu otevrena.');await openDetail(activeStatement.public_id)}catch(error){message(error.message,true)}}async function reversePayment(payment,revision){const reason=prompt('Uvedte duvod storna platby (alespon 3 znaky):','Oprava bankovni platby vyuctovani.');if(reason===null||reason.trim().length<3)return;try{await api(`/api/v1/financial-settlement-statements/${activeStatement.public_id}/bank-payments/${payment}/reverse`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({idempotency_key:crypto.randomUUID(),expected_revision:revision,reason:reason.trim()})});message('Platba vyuctovani byla stornovana.');await openDetail(activeStatement.public_id);await load()}catch(error){message(error.message,true)}}
async function openDetail(id){try{const item=await api(`/api/v1/financial-settlement-statements/${id}`);activeStatement=item;document.querySelector('#detailTitle').textContent=`Vyuctovani ${recipient(item)}`;document.querySelector('#detailCards').innerHTML=`<div class="card"><span>Vynosy</span><strong>${esc(money(item.earning_amount_minor,item.currency))}</strong></div><div class="card"><span>Srazky</span><strong>${esc(money(item.deduction_amount_minor,item.currency))}</strong></div><div class="card"><span>Ciste saldo</span><strong class="${netClass(item.net_balance_minor)}">${esc(money(item.net_balance_minor,item.currency))}</strong></div><div class="card"><span>Stav</span><strong>${esc(labels[item.status]||item.status)}</strong></div><div class="card"><span>Vystupni doklad</span><strong>${esc(item.billing_document?.document_number||item.billing_document?.public_id||'-')}</strong></div>`;renderLifecycleActions(item);renderMaterialization(item);renderBankAdministration(item);document.querySelector('#lineRows').innerHTML=(item.lines||[]).map(line=>`<tr><td>${esc(line.position)}</td><td>${esc(line.source_type)}<br><span class="muted">${esc(line.source_public_id)}</span></td><td>${esc(line.description)}</td><td>${esc(labels[line.effect]||line.effect)}</td><td><b>${esc(money(line.amount_minor,line.currency))}</b></td><td>${esc(line.source_revision)}</td></tr>`).join('')||'<tr><td colspan="6">Bez zdrojovych radku.</td></tr>';document.querySelector('#audit').innerHTML=(item.events||[]).map(event=>`<div class="audit-item"><b>${esc(auditLabel(event.event_type))}</b> | revize ${esc(event.revision)}<br><span class="muted">${esc(event.reason||'')} | ${esc(date(event.occurred_at))}</span></div>`).join('')||'<p class="muted">Bez auditnich udalosti.</p>';document.querySelector('#detailModal').classList.remove('hidden')}catch(error){message(error.message,true)}}
document.querySelector('#openBankEvidence').onclick=()=>{document.querySelector('#bankEvidenceModal').classList.remove('hidden');loadBankEvidence()};document.querySelector('#closeBankEvidence').onclick=()=>document.querySelector('#bankEvidenceModal').classList.add('hidden');document.querySelector('#filterBankEvidence').onclick=loadBankEvidence;document.querySelector('#resetBankEvidence').onclick=()=>{for(const id of ['evidenceDirection','evidenceCurrency','evidenceBookedFrom','evidenceBookedUntil','evidenceReference'])document.querySelector(`#${id}`).value='';document.querySelector('#bankEvidenceDetail').classList.add('hidden');loadBankEvidence()};document.querySelector('#exportReconciliation').onclick=exportReconciliation;document.querySelector('#filter').onclick=()=>{page=1;load()};document.querySelector('#reset').onclick=()=>{for(const id of ['status','partyType','direction','periodFrom','periodUntil'])document.querySelector(`#${id}`).value='';page=1;load()};document.querySelector('#refresh').onclick=load;document.querySelector('#previous').onclick=()=>{if(page>1){page--;load()}};document.querySelector('#next').onclick=()=>{if(page<lastPage){page++;load()}};document.querySelector('#closeDetail').onclick=()=>document.querySelector('#detailModal').classList.add('hidden');document.querySelector('#materializeOutput').onclick=materializeOutput;document.querySelector('#proposeMatch').onclick=proposeMatch;load();
</script>
</body>
</html>
